package com.example.blades360;
import android.app.Activity;
import android.content.*;
import android.net.Uri;
import android.view.WindowManager;
import android.util.Base64;
import org.json.*;
import java.io.*;
import java.security.KeyStore;
import java.util.*;
import javax.crypto.*;
import javax.crypto.spec.GCMParameterSpec;

/** Password encrypted settings, with device-bound secrets rewrapped on import. */
final class FullSettingsBackup {
 static final int EXPORT=3870,IMPORT=3871;
 final MainActivity a;char[] password;boolean busy;
 FullSettingsBackup(MainActivity a){this.a=a;}
 void start(boolean restore){if(busy)return;if(a.vpn!=null&&(a.vpn.active||a.vpn.busy)){message("Disconnect VPN before backing up or restoring settings.");return;}
  if(restore)a.tools.show("Restore all settings?","Replaces saved settings and service logins. Requires app restart. ROMs, saves and media are not included.",a.tools::openBackup,a.tools.action("Cancel",a.tools::openBackup),a.tools.action("Choose encrypted backup",()->prompt(true)));
  else prompt(false);
 }
 void message(String text){a.tools.show("Full settings backup",text,a.tools::openBackup,a.tools.action("Back",a.tools::openBackup));}
 void prompt(boolean restore){a.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);a.tools.editor=new BladesKeyboard(a,restore?"Backup password":"New backup password (12+ characters)","",128,false,value->{if(value.length()<12){message("Use at least 12 characters. Keep this password to restore your backup.");return;}password=value.toCharArray();Intent pick=new Intent(restore?Intent.ACTION_OPEN_DOCUMENT:Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/octet-stream");if(!restore)pick.putExtra(Intent.EXTRA_TITLE,"Blades360-settings.b360");try{a.startActivityForResult(pick,restore?IMPORT:EXPORT);}catch(Exception e){clear();message("Document picker unavailable.");}},()->{a.tools.editor=null;a.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SECURE);a.dashboard.requestFocus();});a.tools.editor.secret=true;}
 void clear(){if(password!=null)Arrays.fill(password,'\0');password=null;}
 boolean result(int request,int result,Intent data){if(request!=EXPORT&&request!=IMPORT)return false;if(result!=Activity.RESULT_OK||data==null||password==null){clear();return true;}busy=true;a.library.save();Uri uri=data.getData();char[] pass=password;password=null;message("Processing encrypted settings…");a.tools.backup.worker.execute(()->{String status;try{if(request==EXPORT){byte[] plain=snapshot().toString().getBytes("UTF-8");byte[] encrypted=SettingsCipher.crypt(plain,pass,true);Arrays.fill(plain,(byte)0);try(OutputStream out=a.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException();out.write(encrypted);}status="Full settings exported, including saved logins. Keep the password safe. ROMs, artwork, saves and media are separate.";}else{byte[] encrypted;try(InputStream in=a.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException();encrypted=BackupArchive.bounded(in,SettingsCipher.MAX);}byte[] plain=SettingsCipher.crypt(encrypted,pass,false);JSONObject root=new JSONObject(new String(plain,"UTF-8"));Arrays.fill(plain,(byte)0);validate(root);JSONObject previous=snapshot();PrivateMediaFile.write(a,"settings-recovery.bin",previous.toString());try{restore(root);}catch(Exception failure){restore(previous);throw failure;}status="All saved settings restored. Close and reopen Blades360 now. Reselect folders on a different device. Artwork can be restored with Import setup.";}}catch(Exception e){status="Could not complete backup. Check password, file integrity, available storage and access.";}finally{Arrays.fill(pass,'\0');}String done=status;a.runOnUiThread(()->{busy=false;if(done.startsWith("All saved settings restored")){a.tools.show("Settings restored",done,null,a.tools.action("Restart Blades360",()->{a.finishAffinity();a.startActivity(new Intent(a,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));}));}else message(done);});});return true;}
 String alias(String store,String key){return store.equals("retroachievements")&&key.equals("key")?"blades-ra-web-key":Arrays.asList("romm","jellyfin","plex").contains(store)&&key.equals("credential")?"blades-romm-key":null;}
 String rewrap(String value,String alias,boolean decrypt)throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias(alias)){android.security.keystore.KeyGenParameterSpec spec=new android.security.keystore.KeyGenParameterSpec.Builder(alias,3).setBlockModes("GCM").setEncryptionPaddings("NoPadding").build();KeyGenerator gen=KeyGenerator.getInstance("AES","AndroidKeyStore");gen.init(spec);gen.generateKey();}Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");java.security.Key key=ks.getKey(alias,null);if(decrypt){String[] parts=value.split(":");cipher.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,Base64.decode(parts[0],2)));return new String(cipher.doFinal(Base64.decode(parts[1],2)),"UTF-8");}cipher.init(Cipher.ENCRYPT_MODE,key);return Base64.encodeToString(cipher.getIV(),2)+":"+Base64.encodeToString(cipher.doFinal(value.getBytes("UTF-8")),2);}
 JSONObject snapshot()throws Exception{JSONObject stores=new JSONObject(),files=new JSONObject();File dir=new File(a.getApplicationInfo().dataDir,"shared_prefs");File[] list=dir.listFiles();if(list!=null)for(File file:list){if(!file.getName().endsWith(".xml"))continue;String name=file.getName().replaceFirst("\\.xml$","");if(!Arrays.asList("emulator_library","controller_mappings","blades_profile","retroachievements","romm","jellyfin","plex","iptv_options","youtube_local","pia_options").contains(name))continue;Map<String,?> values=a.getSharedPreferences(name,0).getAll();JSONObject settings=a.tools.backup.settings(values);if(values.containsKey("games"))settings.put("games",new JSONObject().put("type","string").put("value",values.get("games")));for(Iterator<String> it=settings.keys();it.hasNext();){String key=it.next(),alias=alias(name,key);if(alias!=null)settings.getJSONObject(key).put("value",rewrap(settings.getJSONObject(key).getString("value"),alias,true));}stores.put(name,settings);}
  for(String name:Arrays.asList("iptv-config.bin","pia-login.bin"))if(new File(a.getFilesDir(),name).isFile())files.put(name,PrivateMediaFile.read(a,name));return new JSONObject().put("format","Blades360FullSettings").put("version",1).put("stores",stores).put("privateFiles",files);}
 void validate(JSONObject root)throws Exception{if(!root.getString("format").equals("Blades360FullSettings")||root.getInt("version")!=1)throw new IOException();JSONObject stores=root.getJSONObject("stores"),files=root.getJSONObject("privateFiles");if(stores.length()>100)throw new IOException();for(Iterator<String> it=stores.keys();it.hasNext();){String name=it.next();if(!Arrays.asList("emulator_library","controller_mappings","blades_profile","retroachievements","romm","jellyfin","plex","iptv_options","youtube_local","pia_options").contains(name))throw new IOException();JSONObject values=stores.getJSONObject(name);if(values.length()>10000)throw new IOException();for(Iterator<String> keys=values.keys();keys.hasNext();){String key=keys.next();JSONObject v=values.getJSONObject(key);if(key.length()>512)throw new IOException();if(name.equals("emulator_library")&&!key.equals("games"))a.tools.backup.validateKnown(key,v);if(name.equals("emulator_library")&&key.equals("games")){JSONArray games=new JSONArray(v.getString("value"));if(games.length()>10000)throw new IOException();for(int i=0;i<games.length();i++){JSONObject game=games.getJSONObject(i);String uri=game.getString("uri");if(!(uri.startsWith("content://")||uri.startsWith("file://"))||game.getString("name").length()>2048)throw new IOException();}}String t=v.getString("type");switch(t){case "string":v.getString("value");break;case "boolean":v.getBoolean("value");break;case "int":v.getInt("value");break;case "long":v.getLong("value");break;case "float":if(!Double.isFinite(v.getDouble("value")))throw new IOException();break;case "set":JSONArray set=v.getJSONArray("value");for(int i=0;i<set.length();i++)set.getString(i);break;default:throw new IOException();}}}for(Iterator<String> it=files.keys();it.hasNext();){String name=it.next();if(!Arrays.asList("iptv-config.bin","pia-login.bin").contains(name))throw new IOException();new JSONObject(files.getString(name));}}
 void restore(JSONObject root)throws Exception{JSONObject stores=root.getJSONObject("stores"),files=root.getJSONObject("privateFiles");for(Iterator<String> it=stores.keys();it.hasNext();){String name=it.next();JSONObject values=stores.getJSONObject(name);SharedPreferences.Editor edit=a.getSharedPreferences(name,0).edit().clear();for(Iterator<String> keys=values.keys();keys.hasNext();){String key=keys.next();JSONObject v=values.getJSONObject(key);switch(v.getString("type")){case "string":String value=v.getString("value"),alias=alias(name,key);edit.putString(key,alias==null?value:rewrap(value,alias,false));break;case "boolean":edit.putBoolean(key,v.getBoolean("value"));break;case "int":edit.putInt(key,v.getInt("value"));break;case "long":edit.putLong(key,v.getLong("value"));break;case "float":edit.putFloat(key,(float)v.getDouble("value"));break;case "set":Set<String> set=new HashSet<>();JSONArray arr=v.getJSONArray("value");for(int i=0;i<arr.length();i++)set.add(arr.getString(i));edit.putStringSet(key,set);}}if(!edit.commit())throw new IOException();}for(Iterator<String> it=files.keys();it.hasNext();){String name=it.next();PrivateMediaFile.write(a,name,files.getString(name));}}
}
